test('invoiceTotals returns correct subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 95000 + 120000;
  const devVAT = Math.round((95000 * 21) / 100);
  const logoVAT = Math.round((120000 * 21) / 100);

  assert.deepEqual(totals, {
    subtotal,
    discount: 0,
    vat: devVAT + logoVAT,
    total: subtotal + devVAT + logoVAT,
  });
});

test('invoiceTotals with single line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'SUPPORT-HOUR', qty: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 7250;

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.total, subtotal + totals.vat);
});

test('invoiceTotals with many lines', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'COPY-HOUR', qty: 5 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 20 },
    ],
  }).value;

  const expected = 10 * 9500 + 5 * 6000 + 3 * 7250 + 20 * 980;
  const vat = Math.round((expected * 21) / 100);
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, expected + vat);
});

test('invoiceTotals returns whole cents', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
