test('invoiceTotals includes subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const devTotal = 95000;
  const devDiscount = Math.round((devTotal * 10) / 100);
  const devAfterDiscount = devTotal - devDiscount;
  const devVAT = Math.round((devAfterDiscount * 21) / 100);
  const logoVAT = Math.round((120000 * 21) / 100);

  assert.equal(totals.subtotal, 95000 + 120000);
  assert.equal(totals.discount, devDiscount);
  assert.equal(totals.vat, devVAT + logoVAT);
  assert.equal(totals.total, 95000 - devDiscount + 120000 + devVAT + logoVAT);
});

